+package cli
+
+import (
+	"bufio"
+	"context"
+	"fmt"
+	"io"
+	"os/exec"
+	"strconv"
+	"strings"
+)
+
+var runGitBlamePorcelain = func(ctx context.Context, path string) (string, error) {
+	cmd := exec.CommandContext(ctx, "git", "blame", "--line-porcelain", "--", path)
+	out, err := cmd.Output()
+	if err != nil {
+		return "", err
+	}
+	return string(out), nil
+}
+
+func loadWhyBlocks(ctx context.Context, path string) ([]whyBlock, error) {
+	out, err := runGitBlamePorcelain(ctx, path)
+	if err != nil {
+		return nil, err
+	}
+	return parseWhyBlamePorcelain(strings.NewReader(out))
+}
+
+func parseWhyBlamePorcelain(r io.Reader) ([]whyBlock, error) {
+	scanner := bufio.NewScanner(r)
+	var (
+		blocks []whyBlock
+		cur    *whyBlock
+	)
+
+	for {
+		header, ok, err := nextWhyBlameHeader(scanner)
+		if err != nil {
+			return nil, err
+		}
+		if !ok {
+			break
+		}
+
+		block, err := whyBlockFromHeader(scanner, header)
+		if err != nil {
+			return nil, err
+		}
+
+		if cur != nil && cur.Commit.Hash == block.Commit.Hash && cur.EndLine+1 == block.StartLine {
+			cur.EndLine = block.EndLine
+			cur.CodeLines = append(cur.CodeLines, block.CodeLines...)
+			continue
+		}
+
+		if cur != nil {
+			blocks = append(blocks, *cur)
+		}
+		cur = &block
+	}
+
+	if cur != nil {
+		blocks = append(blocks, *cur)
+	}
+
+	return blocks, nil
+}
+
+type whyBlameHeader struct {
+	Hash     string
+	EndLine  int
+	Meta     whyCommitInfo
+	LineText string
+}
+
+func nextWhyBlameHeader(scanner *bufio.Scanner) (whyBlameHeader, bool, error) {
+	for scanner.Scan() {
+		line := scanner.Text()
+		if strings.HasPrefix(line, "\t") {
+			return whyBlameHeader{}, false, fmt.Errorf("unexpected content line without header: %q", line)
+		}
+		if strings.TrimSpace(line) == "" {
+			continue
+		}
+
+		fields := strings.Fields(line)
+		if len(fields) < 3 {
+			return whyBlameHeader{}, false, fmt.Errorf("invalid blame header: %q", line)
+		}
+
+		endLine, err := strconv.Atoi(fields[2])
+		if err != nil {
+			return whyBlameHeader{}, false, fmt.Errorf("invalid blame line number %q: %w", fields[2], err)
+		}
+
+		header := whyBlameHeader{
+			Hash:    fields[0],
+			EndLine: endLine,
+			Meta: whyCommitInfo{
+				Hash:      fields[0],
+				ShortHash: shortCommitHash(fields[0]),
+			},
+		}
+
+		for scanner.Scan() {
+			line := scanner.Text()
+			if line == "" {
+				continue
+			}
+			if strings.HasPrefix(line, "\t") {
+				header.LineText = strings.TrimPrefix(line, "\t")
+				return header, true, nil
+			}
+			if strings.HasPrefix(line, "author ") {
+				header.Meta.Author = strings.TrimPrefix(line, "author ")
+				continue
+			}
+			if strings.HasPrefix(line, "summary ") {
+				header.Meta.Subject = strings.TrimPrefix(line, "summary ")
+				continue
+			}
+		}
+		if err := scanner.Err(); err != nil {
+			return whyBlameHeader{}, false, err
+		}
+		return whyBlameHeader{}, false, io.EOF
+	}
+
+	if err := scanner.Err(); err != nil {
+		return whyBlameHeader{}, false, err
+	}
+	return whyBlameHeader{}, false, nil
+}
+
+func whyBlockFromHeader(scanner *bufio.Scanner, header whyBlameHeader) (whyBlock, error) {
+	block := whyBlock{
+		StartLine: header.EndLine,
+		EndLine:   header.EndLine,
+		Commit:    header.Meta,
+		CodeLines: []string{header.LineText},
+		Detail:    whyDetailCommit,
+	}
+	return block, nil
+}
+
+func shortCommitHash(hash string) string {
+	if len(hash) <= 10 {
+		return hash
+	}
+	return hash[:10]
+}
